  for(const [p,b]of originals)await fresh(RUN+'/originals/'+p,b);await fresh(RUN+'/plan.json',{sourceCommit:c.sourceCommit,binding,originalGlobals:await snap(GLOBALS),copies:copyRows,result:resultRef,outputs:[...updates].map(([p,s])=>({path:p,sha256:sha(s)}))});for(const r of copyRows)await fresh(r.to,await checked(r.from));await fresh(resultPath,result);await fresh(FOLDER+'/README.md',readme);for(const [p,s]of updates)await fs.writeFile(ROOT+'/'+p,s);await fresh(FOLDER+'/checkpoint.json',{schemaVersion:1,pass:true,sourceCommit:c.sourceCommit,result:resultRef,producer:await ref(HERE+'/checkpoint.mjs'),outputs:await snap([...GLOBALS,resultPath,FOLDER+'/README.md',...copyRows.map(r=>r.to)]),applicationChecksRun:false,buildsRun:false,allStatusesUnchanged:true,releaseReady:false});console.log(json({mode:'record',result:resultRef}));
