function preserve(state,trace,oldState,oldTrace){
  const a=structuredClone(state),b=structuredClone(oldState),x=structuredClone(trace),y=structuredClone(oldTrace);
  for(const r of [a,b]){delete r.updatedAt;delete r.headSha;delete r.verificationCache[CACHE];delete r.resume.nextAction;for(const k of ['contextFiles','doNotRepeat'])delete r.resume[k];const s=r.stages.find(s=>s.id==='S15');delete s.artifacts;delete s.lastGreenCommands;for(const c of s.criteria.filter(c=>TARGETS.includes(c.id.replace('S15.',''))))for(const k of ['commit','notes','evidence','lastValidatedAt'])delete c[k];}
  for(const r of [x,y])for(const q of r.requirements.filter(q=>TARGETS.includes(q.id)))for(const k of ['commit','notes','evidence','implementationFiles','tests'])delete q[k];assert.deepEqual(a,b);assert.deepEqual(x,y);
  for(const [now,old,keys]of [[state.resume,oldState.resume,['contextFiles','doNotRepeat']],[state.stages.find(s=>s.id==='S15'),oldState.stages.find(s=>s.id==='S15'),['artifacts','lastGreenCommands']]])for(const k of keys)assert.deepEqual(now[k].slice(0,old[k].length),old[k]);
  for(const id of TARGETS)for(const [now,old,keys]of [[state.stages.find(s=>s.id==='S15').criteria.find(c=>c.id==='S15.'+id),oldState.stages.find(s=>s.id==='S15').criteria.find(c=>c.id==='S15.'+id),['evidence']],[trace.requirements.find(q=>q.id===id),oldTrace.requirements.find(q=>q.id===id),['evidence','implementationFiles','tests']]])for(const k of keys)assert.deepEqual(now[k].slice(0,old[k].length),old[k]);
  assert.equal(state.currentStageId,'S03');assert.equal(state.currentCriterionId,'S03.acceptance');assert.equal(state.resume.firstOpenCriterion,'S03.acceptance');
}
async function recorded(){const plan=await read(RUN+'/plan.json'),c=await evidence(plan.binding),checkpoint=await read(FOLDER+'/checkpoint.json');assert.equal(checkpoint.pass,true);assert.equal(checkpoint.sourceCommit,c.sourceCommit);assert.deepEqual(checkpoint.result,await ref(FOLDER+'/result.json'));assert.deepEqual(checkpoint.producer,await ref(HERE+'/checkpoint.mjs'));await refs(checkpoint.outputs);const state=await read(STATE),trace=await read(TRACE);preserve(state,trace,await read(RUN+'/originals/'+STATE),await read(RUN+'/originals/'+TRACE));assert.equal(state.headSha,c.sourceCommit);assert.equal(state.resume.nextAction,NEXT);assert.equal((await fs.readFile(ROOT+'/'+CSV,'utf8')).replaceAll('\r\n','\n'),await csv(trace));assert.deepEqual(lines(git(['diff','--name-only'])).sort(),GLOBALS.slice().sort());assert.ok(lines(git(['ls-files','--others','--exclude-standard'])).every(p=>p.startsWith(FOLDER+'/')));for(const r of plan.originalGlobals)await checked({path:RUN+'/originals/'+r.path,sha256:r.sha256});return {plan,c,checkpoint};}
